"""Fulfillment endpoints for warehouse operations."""

from __future__ import annotations

from typing import Any

from orders.application.errors import Conflict, OrderNotFound, ProductNotFound
from orders.application.fulfilment_service import FulfilmentService
from orders.controllers.http import InvalidRequest, Response, bad_request, conflict, not_found, require_positive_int, require_str, require_non_negative_int


class FulfilmentController:
    def __init__(self, service: FulfilmentService) -> None:
        self._service = service

    def handle_packing_slip(self, order_id: str) -> Response:
        try:
            return Response(200, self._service.get_packing_slip(order_id))
        except OrderNotFound:
            return not_found("order")
        except Conflict as exc:
            return conflict(exc)

    def handle_low_stock(self, request: dict[str, Any]) -> Response:
        try:
            threshold = require_non_negative_int(request.get("threshold"), "threshold")
        except InvalidRequest as exc:
            return bad_request(exc)
        return Response(200, self._service.get_low_stock_products(threshold))

    def handle_restock(self, request: dict[str, Any]) -> Response:
        try:
            sku = require_str(request, "sku")
            quantity = require_positive_int(request.get("quantity"), "quantity")
        except InvalidRequest as exc:
            return bad_request(exc)
        try:
            return Response(200, self._service.restock(sku, quantity))
        except ProductNotFound:
            return not_found("product")

    def handle_fulfilment_summary(self) -> Response:
        return Response(200, self._service.get_fulfilment_summary())

"""Fulfillment operations for warehouse packing and shipping."""

from __future__ import annotations

from typing import Any

from orders.application.errors import Conflict, OrderNotFound, ProductNotFound
from orders.infrastructure.catalog import InMemoryProductCatalog
from orders.infrastructure.customers import InMemoryCustomerRepository
from orders.infrastructure.repository import InMemoryOrderRepository
from orders.infrastructure.stock import InMemoryStockRepository


class FulfilmentService:
    def __init__(
        self,
        orders: InMemoryOrderRepository,
        customers: InMemoryCustomerRepository,
        catalog: InMemoryProductCatalog,
        stock: InMemoryStockRepository,
    ) -> None:
        self._orders = orders
        self._customers = customers
        self._catalog = catalog
        self._stock = stock

    def get_packing_slip(self, order_id: str) -> dict[str, Any]:
        order = self._orders.get(order_id)
        if order is None:
            raise OrderNotFound(order_id)
        if order.status == "cancelled":
            raise Conflict("cannot pack a cancelled order")
        customer = self._customers.get(order.customer_id)
        lines = []
        for item in order.items:
            product = self._catalog.get(item.sku)
            lines.append({
                "sku": item.sku,
                "name": product.name if product else item.sku,
                "quantity": item.quantity,
            })
        return {
            "order_id": order.order_id,
            "customer_name": customer.name if customer else "",
            "lines": lines,
        }

    def get_low_stock_products(self, threshold: int) -> dict[str, Any]:
        products = []
        for product in self._catalog.list_all():
            if product.active and self._stock.get(product.sku) < threshold:
                products.append({
                    "sku": product.sku,
                    "name": product.name,
                    "on_hand": self._stock.get(product.sku),
                })
        products.sort(key=lambda p: (p["on_hand"], p["sku"]))
        return {"products": products}

    def restock(self, sku: str, quantity: int) -> dict[str, Any]:
        if self._catalog.get(sku) is None:
            raise ProductNotFound(sku)
        new_level = self._stock.get(sku) + quantity
        self._stock.set(sku, new_level)
        return {"sku": sku, "on_hand": new_level}

    def get_fulfilment_summary(self) -> dict[str, Any]:
        open_orders = 0
        units_to_pick = 0
        for order in self._orders.list_all():
            if order.status != "cancelled":
                open_orders += 1
                for item in order.items:
                    units_to_pick += item.quantity
        low_stock_products = 0
        for product in self._catalog.list_all():
            if product.active and self._stock.get(product.sku) < 5:
                low_stock_products += 1
        return {
            "open_orders": open_orders,
            "units_to_pick": units_to_pick,
            "low_stock_products": low_stock_products,
        }
